def write_entry(repo, relpath, payload_b64, binary):
    raw = base64.b64decode(payload_b64)
    data = raw if binary else gzip.decompress(raw)
    dest = os.path.join(repo, relpath)
    os.makedirs(os.path.dirname(dest) or repo, exist_ok=True)
    if os.path.exists(dest):
        with open(dest, "rb") as fh:
            if hashlib.sha256(fh.read()).hexdigest() == hashlib.sha256(data).hexdigest():
                print(f"  = unchanged  {relpath}")
                return
    fd, tmp = tempfile.mkstemp(dir=os.path.dirname(dest) or repo, prefix=".apply-")
    with os.fdopen(fd, "wb") as fh:
        fh.write(data)
    os.replace(tmp, dest)
    kind = "binary" if binary else "text  "
    print(f"  + wrote {kind} {relpath} ({len(data):,} bytes)")

def main():
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[1])
    ap.add_argument("--repo", default=os.getcwd(), help="path to the aria-residential repo clone")
    ap.add_argument("--skip-install", action="store_true", help="skip npm install")
    args = ap.parse_args()
    repo = os.path.abspath(args.repo)
    if not os.path.isdir(os.path.join(repo, "src")):
        sys.exit(f"Not an aria-residential checkout: {repo} (pass --repo)")

    print(f"Applying changes to: {repo}\n")
    for relpath, payload in FILES.items():
        write_entry(repo, relpath, payload, relpath not in TEXT_FILES)

    if not args.skip_install:
        print("\nRunning npm install (syncs lockfile with the new quick-liquid dependency)...")
        try:
            subprocess.run(["npm", "install", "--legacy-peer-deps"], cwd=repo, check=True)
        except FileNotFoundError:
            print("  ! npm not found — run `npm install` manually.", file=sys.stderr)
        except subprocess.CalledProcessError as e:
            print(f"  ! npm install failed (exit {e.returncode}) — run it manually.", file=sys.stderr)

    print("""
Done. The repo now matches the final delivered version.
Next steps:
  npm run dev      # http://localhost:3000
  npm run build    # production build (includes the mobile GLB in the deploy output)
Key files to review:
  src/components/three/GaussianSplat.tsx            (Task 1 fix + comments)
  src/components/Walkthrough/WalkthroughScene.tsx   (adaptive DPR)
  src/components/three/MainBuildingModel.tsx        (mobile model tier)
  src/components/CityScene/cityHeightfield.ts       (tour roofline guard)
  src/components/CityScene/PersistentCityCanvas.tsx (guarded keyframes)
  src/components/ui/liquid-glass.tsx                (quick-liquid presets)
""")

if __name__ == '__main__':
    main()